1	package numeric
2	
3	import (
4		"encoding/base64"
5		"encoding/json"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"sync/atomic"
12		"time"
13		"unicode/utf8"
14	)
15	
16	// rawBase64Prefix 标记 _raw 字段中的值是原始字节的 base64 编码。
17	// ':' 不在 base64 字母表内，普通文本（即使本身像 base64，如 "abcd"）
18	// 不会以该前缀开头；而 _raw 字段由本版本写入，旧归档不含此字段，
19	// 因此标记无歧义。
20	const rawBase64Prefix = "base64:"
21	
22	// unmarshalRaw 恢复 rawIdentity 写出的字段；带 base64 前缀的兜底值解码回
23	// 原始字节，普通 JSON 字符串原样返回。
24	func unmarshalRaw(s string) (string, error) {
25		if strings.HasPrefix(s, rawBase64Prefix) {
26			b, err := base64.StdEncoding.DecodeString(s[len(rawBase64Prefix):])
27			if err != nil {
28				return "", fmt.Errorf("numeric: 标识原始字节解码失败: %w", err)
29			}
30			return string(b), nil
31		}
32		return s, nil
33	}
34	
35	// identityRaw 携带提交人、请求号的完整字节兜底表示。只有当对应字段含
36	// 非法 UTF-8 字节时相应成员才非空；普通文本记录不写这两个字段，
37	// 保持旧格式归档可直接打开。
38	type identityRaw struct {
39		Submitter string `json:"submitter_raw,omitempty"`
40		RequestID string `json:"request_id_raw,omitempty"`
41	}
42	
43	// rawIdentity 在标识含非法 UTF-8 字节时构造完整字节兜底字段；
44	// 两个标识都是合法 UTF-8 时返回 nil，记录与旧格式完全一致。
45	func rawIdentity(submitter, requestID string) *identityRaw {
46		if utf8.ValidString(submitter) && utf8.ValidString(requestID) {
47			return nil
48		}
49		raw := &identityRaw{}
50		if !utf8.ValidString(submitter) {
51			raw.Submitter = rawBase64Prefix + base64.StdEncoding.EncodeToString([]byte(submitter))
52		}
53		if !utf8.ValidString(requestID) {
54			raw.RequestID = rawBase64Prefix + base64.StdEncoding.EncodeToString([]byte(requestID))
55		}
56		return raw
57	}
58	
59	// resolveIdentity 恢复提交人、请求号：_raw 兜底字段存在且非空时以其
60	// 解码出的完整字节为准，否则使用 JSON 字符串字段（旧归档与普通文本）。
61	func resolveIdentity(plainSub, plainReq string, raw *identityRaw) (string, string, error) {
62		var err error
63		sub, req := plainSub, plainReq
64		if raw != nil {
65			if raw.Submitter != "" {
66				if sub, err = unmarshalRaw(raw.Submitter); err != nil {
67					return "", "", err
68				}
69			}
70			if raw.RequestID != "" {
71				if req, err = unmarshalRaw(raw.RequestID); err != nil {
72					return "", "", err
73				}
74			}
75		}
76		return sub, req, nil
77	}
78	
79	// recordVersion 是落盘记录格式的版本标记。
80	const recordVersion = "numeric-job-v1"
81	
82	// storedJob 是作业在内存中的完整状态，所有字段均由 Store.mu 保护。
83	type storedJob struct {
84		id           uint64
85		submitter    string
86		requestID    string
87		seed         int64
88		values       []int64
89		dependencies []uint64 // 有序直接上游作业号；空表示无依赖
90	
91		queuedAt   time.Time
92		startedAt  time.Time
93		finishedAt time.Time
94	
95		status        Status
96		failureReason string
97		blockerID     uint64
98	
99		// 成功后保存的有效输入与归档（与 succeeded 状态同一次原子写入）。
100		effectiveValues []int64
101		archive         *Archive
102	
103		// canceled 仅存于内存：运行中的作业收到取消/关闭请求后置位，
104		// 计算循环据此尽快中止；终态不会依赖它落盘（终态本身会持久化）。
105		canceled atomic.Bool
106	}
107	
108	// jobRecord 是 storedJob 的落盘 JSON 表示。成功状态与归档在同一记录内，
109	// 一次 temp-file + rename 原子写入，因此对外不会出现“成功却没有结果”。
110	type jobRecord struct {
111		Version string `json:"version"`
112	
113		ID        uint64 `json:"id"`
114		Submitter string `json:"submitter"`
115		RequestID string `json:"request_id"`
116		// IdentityRaw 仅在提交人或请求号含非法 UTF-8 字节时出现，按完整字节
117		// 保真恢复标识；合法 UTF-8（含 U+0000）时缺省，记录与旧格式一致。
118		IdentityRaw   *identityRaw `json:"identity_raw,omitempty"`
119		Seed          int64        `json:"seed"`
120		Values        []int64      `json:"values"`
121		HasDependency bool         `json:"has_dependency"`
122		DependencyID  uint64       `json:"dependency_id"`
123		// Dependencies 为有序直接上游作业号；旧格式记录无此字段，
124		// 恢复时由 HasDependency/DependencyID 推导。
125		Dependencies []uint64 `json:"dependencies,omitempty"`
126	
127		QueuedAt   time.Time `json:"queued_at"`
128		StartedAt  time.Time `json:"started_at,omitempty"`
129		FinishedAt time.Time `json:"finished_at,omitempty"`
130	
131		Status        Status `json:"status"`
132		FailureReason string `json:"failure_reason,omitempty"`
133		BlockerID     uint64 `json:"blocker_id,omitempty"`
134	
135		EffectiveValues []int64  `json:"effective_values,omitempty"`
136		Archive         *Archive `json:"archive,omitempty"`
137	}
138	
139	func jobFileName(id uint64) string {
140		return fmt.Sprintf("job-%020d.json", id)
141	}
142	
143	func (s *Store) jobPath(j *storedJob) string {
144		return filepath.Join(s.dir, jobFileName(j.id))
145	}
146	
147	func encodeRecord(j *storedJob) ([]byte, error) {
148		r := jobRecord{
149			Version: recordVersion,
150	
151			ID:            j.id,
152			Submitter:     j.submitter,
153			RequestID:     j.requestID,
154			IdentityRaw:   rawIdentity(j.submitter, j.requestID),
155			Seed:          j.seed,
156			Values:        append([]int64(nil), j.values...),
157			HasDependency: len(j.dependencies) > 0,
158			DependencyID:  depID(j),
159			Dependencies:  append([]uint64(nil), j.dependencies...),
160	
161			QueuedAt:      j.queuedAt,
162			StartedAt:     j.startedAt,
163			FinishedAt:    j.finishedAt,
164			Status:        j.status,
165			FailureReason: j.failureReason,
166			BlockerID:     j.blockerID,
167	
168			EffectiveValues: append([]int64(nil), j.effectiveValues...),
169			Archive:         j.archive,
170		}
171		return json.MarshalIndent(&r, "", "  ")
172	}
173	
174	// depID 返回首个直接上游作业号（无依赖时为 0）。
175	func depID(j *storedJob) uint64 {
176		if len(j.dependencies) == 0 {
177			return 0
178		}
179		return j.dependencies[0]
180	}
181	
182	// persist 在已持锁的情况下原子写一条作业记录。
183	func (s *Store) persist(j *storedJob) error {
184		// 测试用故障注入点（生产代码中 persistFault 恒为 nil）。
185		if s.persistFault != nil {
186			if err := s.persistFault(j); err != nil {
187				return err
188			}
189		}
190		data, err := encodeRecord(j)
191		if err != nil {
192			return err
193		}
194		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
195	}
196	
197	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
198	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
199	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
200		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
201		if err != nil {
202			return err
203		}
204		tmpName := tmp.Name()
205		cleanup := true
206		defer func() {
207			if cleanup {
208				_ = os.Remove(tmpName)
209			}
210		}()
211	
212		if _, err := tmp.Write(data); err != nil {
213			_ = tmp.Close()
214			return err
215		}
216		if err := tmp.Sync(); err != nil {
217			_ = tmp.Close()
218			return err
219		}
220		if err := tmp.Close(); err != nil {
221			return err
222		}
223		if err := os.Chmod(tmpName, perm); err != nil {
224			return err
225		}
226		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
227			return err
228		}
229		cleanup = false
230		syncDir(dir)
231		return nil
232	}
233	
234	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
235	func syncDir(dir string) {
236		if d, err := os.Open(dir); err == nil {
237			_ = d.Sync()
238			_ = d.Close()
239		}
240	}
241	
242	// loadDir 扫描目录中的全部作业记录并重建内存索引。
243	//
244	// 恢复规则：
245	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
246	//   - 成功记录缺少归档、校验值对不上，实际输入与原始参数或直接依赖数量
247	//     不对应，或归档数值结果与有效输入按计算规则应得的结果不符时，
248	//     fail-closed 地标记为失败，维持“成功必有完整归档”的不变量；
249	//   - 有依赖的成功记录还要求每个直接上游都存在、恢复后仍是带完整归档的
250	//     成功状态，且实际输入的追加部分逐项等于这些上游按保存的依赖顺序
251	//     排列的总和；上游不可用的同样改判为失败，其失败原因指出直接上游、
252	//     BlockerID 沿链条保留最初的根因（与运行中依赖失败同一规则）；
253	//     仅追加输入对不上而上游全部有效的属于本作业自身归档有误，BlockerID
254	//     保持 0。仍在排队的作业在同一趟升序扫描中按既有依赖规则级联失败。
255	func loadDir(dir string) ([]*storedJob, uint64, error) {
256		entries, err := os.ReadDir(dir)
257		if err != nil {
258			return nil, 0, err
259		}
260		var jobs []*storedJob
261		var maxID uint64
262		for _, e := range entries {
263			name := e.Name()
264			if e.IsDir() {
265				continue
266			}
267			// 清理上一进程崩溃时可能残留的原子写临时文件。
268			if strings.HasPrefix(name, ".tmp-") {
269				_ = os.Remove(filepath.Join(dir, name))
270				continue
271			}
272			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
273				continue
274			}
275			path := filepath.Join(dir, name)
276			data, err := os.ReadFile(path)
277			if err != nil {
278				return nil, 0, err
279			}
280			var r jobRecord
281			if err := json.Unmarshal(data, &r); err != nil {
282				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
283			}
284			if r.Version != recordVersion {
285				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
286			}
287			// 提交人、请求号按完整字节恢复：含非法 UTF-8 字节时以
288			// identity_raw 兜底字段为准，普通文本（含 U+0000）与旧归档原样使用。
289			submitter, requestID, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
290			if err != nil {
291				return nil, 0, fmt.Errorf("numeric: 记录 %s 标识损坏: %w", name, err)
292			}
293			// 成功归档内嵌同一份标识，同样按其自身兜底字段恢复，保证顶层记录
294			// 与归档中的参数逐字节一致。
295			if r.Archive != nil {
296				aSub, aReq, aErr := resolveIdentity(r.Archive.Submitter, r.Archive.RequestID, r.Archive.IdentityRaw)
297				if aErr != nil {
298					return nil, 0, fmt.Errorf("numeric: 记录 %s 归档标识损坏: %w", name, aErr)
299				}
300				r.Archive.Submitter = aSub
301				r.Archive.RequestID = aReq
302			}
303			switch r.Status {
304			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
305			default:
306				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
307			}
308			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
309			// 恢复为只含一个作业号的列表（语义与提交时一致）。
310			deps := append([]uint64(nil), r.Dependencies...)
311			if len(deps) == 0 && r.HasDependency {
312				deps = []uint64{r.DependencyID}
313			}
314			j := &storedJob{
315				id:           r.ID,
316				submitter:    submitter,
317				requestID:    requestID,
318				seed:         r.Seed,
319				values:       append([]int64(nil), r.Values...),
320				dependencies: deps,
321	
322				queuedAt:   r.QueuedAt,
323				startedAt:  r.StartedAt,
324				finishedAt: r.FinishedAt,
325	
326				status:        r.Status,
327				failureReason: r.FailureReason,
328				blockerID:     r.BlockerID,
329	
330				effectiveValues: append([]int64(nil), r.EffectiveValues...),
331				archive:         r.Archive,
332			}
333			if j.status == StatusRunning {
334				j.status = StatusFailed
335				j.failureReason = "计算被中断：归档上次关闭时作业仍在运行"
336				j.blockerID = 0
337				if j.finishedAt.IsZero() {
338					j.finishedAt = time.Now().UTC()
339				}
340				j.effectiveValues = nil
341				j.archive = nil
342				// 就地重写恢复后的终态。
343				if data, err := encodeRecord(j); err == nil {
344					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
345				}
346			}
347			if j.status == StatusSucceeded {
348				// 除完整性外，还必须满足两条独立的对应/复算规则：
349				//  1. 实际输入与原始参数、直接依赖数量逐项对应——原始序列非空且
350				//     按原次序完整出现在实际输入开头，总长度恰为原始长度加上直接
351				//     依赖数；摘要、日志、校验值只与“实际输入”绑定，换成另一份
352				//     序列（如 [-3,2] 冒充 [2,-3]）仍能全套自洽，只有按位置比对
353				//     原始参数与依赖数量才能识别。
354				//  2. 归档中的数值结果必须与实际输入按既有计算规则应得的结果一致：
355				//     日志、摘要与校验值都可能与错误数字自洽，只有按保存的实际
356				//     输入复算才能识别。
357				// 任一不符合都按损坏归档处理。第三条规则——追加部分逐项等于各
358				// 直接上游恢复后的总和——需要全部记录恢复完毕才能核对，
359				// 在排序后的第二趟扫描中执行。
360				var invalidReason string
361				switch {
362				case !archiveIntact(j):
363					invalidReason = "归档不完整或校验值不一致，成功结果不可用"
364				case !effectiveInputsCorrespond(j):
365					invalidReason = "实际输入与原始参数或依赖数量不符，成功结果不可用"
366				case !archiveResultsValid(j):
367					invalidReason = "归档数值结果与有效输入按计算规则应得的结果不符，成功结果不可用"
368				}
369				if invalidReason != "" {
370					j.status = StatusFailed
371					j.failureReason = invalidReason
372					// 归档自身校验不通过：属于本作业自身失败，不携带阻断根因。
373					j.blockerID = 0
374					if j.finishedAt.IsZero() {
375						j.finishedAt = time.Now().UTC()
376					}
377					j.effectiveValues = nil
378					j.archive = nil
379					if data, err := encodeRecord(j); err == nil {
380						_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
381					}
382				}
383			}
384			jobs = append(jobs, j)
385			if j.id > maxID {
386				maxID = j.id
387			}
388		}
389		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
390		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
391		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
392		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
393		// 依赖链在单趟级联扫描中漏掉失败传播）。
394		sort.Slice(jobs, func(a, b int) bool {
395			return jobs[a].id < jobs[b].id
396		})
397		// 第二趟：按作业号升序单趟处理依赖失效。直接上游在提交时必须已存在，
398		// 上游作业号必然更小，因此每个作业被处理时其全部直接上游都已是本次恢复
399		// 确定的最终状态——上游被改判失败时携带的根因作业号可直接沿链条继承，
400		// 不会在每经过一个已归档的中间作业时重新起算。
401		//
402		// 两类作业遵守同一项归因规则（与正常运行中的依赖失败一致）：失败原因
403		// 指出当前作业的直接上游，BlockerID 沿链条保留最初使结果不可用的根因；
404		// 只有本作业自身归档有误（上游全部有效、仅保存的追加输入不符）时
405		// BlockerID 才保持 0。
406		//   - 带依赖的成功记录：追加部分与上游恢复后的结果逐项核对；
407		//   - 排队记录：按保存的依赖顺序选取最靠前的不可用上游（已失败/取消，
408		//     或记录缺失），立即级联失败，不再等待。
409		byID := make(map[uint64]*storedJob, len(jobs))
410		for _, j := range jobs {
411			byID[j.id] = j
412		}
413		// failRestored 把恢复阶段判定失败的作业就地改判并原子改写落盘记录，
414		// 使按作业号读取、按提交人列举与磁盘记录保留相同的根因。
415		failRestored := func(j *storedJob, reason string, root uint64) {
416			j.status = StatusFailed
417			j.failureReason = reason
418			j.blockerID = root
419			if j.finishedAt.IsZero() {
420				j.finishedAt = time.Now().UTC()
421			}
422			j.effectiveValues = nil
423			j.archive = nil
424			if data, err := encodeRecord(j); err == nil {
425				_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
426			}
427		}
428		for _, j := range jobs {
429			if len(j.dependencies) == 0 {
430				continue
431			}
432			switch j.status {
433			case StatusSucceeded:
434				// 第一趟：按保存的依赖顺序找最靠前的不可用上游（记录缺失或恢复后
435				// 未保持带完整归档的成功状态）。
436				directID, dep, unavailable := pickBlockingUpstream(j, byID, restoredArchiveUpstreamBlocked)
437				if unavailable {
438					// 因直接上游结果失效而失败：根因沿该上游已有的阻断信息保留，
439					// 直接上游记录缺失时以缺失的作业号本身作为根因。
440					root := blockerRoot(dep, directID)
441					failRestored(j, blockedFailureReason(restoredArchiveHead(directID), dep, directID, root), root)
442					continue
443				}
444				// 第二趟：直接上游全部存在且有效，只是本作业保存的追加输入与上游
445				// 总和按位置对不上——属于本作业自身归档有误，不把有效上游判成
446				// 失败或归因给它，BlockerID 保持 0。
447				if _, detail, mismatch := firstAppendedMismatch(j, byID); mismatch {
448					failRestored(j, detail, 0)
449				}
450			case StatusQueued:
451				// 按保存的依赖顺序选取最靠前的不可用上游；其他上游作业号更小
452				// 或失败原因不同都不能改变这个选择。
453				directID, direct, blocked := pickBlockingUpstream(j, byID, restoredQueuedUpstreamBlocked)
454				if !blocked {
455					continue // 上游仍在排队等情况：继续等待，不挡住其他作业。
456				}
457				root := blockerRoot(direct, directID)
458				if direct == nil {
459					// 直接上游的记录在归档目录中缺失，其结果不可能再变为可用：
460					// 以缺失的作业号作为根因，并明确说明结果无法使用。
461					failRestored(j, blockedFailureReason(restoredMissingHead(directID), nil, directID, root), root)
462					continue
463				}
464				failRestored(j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
465			}
466		}
467		return jobs, maxID, nil
468	}
469	
470	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
471	func archiveIntact(j *storedJob) bool {
472		a := j.archive
473		if a == nil {
474			return false
475		}
476		// 归档中的原始参数必须与记录顶层字段一致。
477		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
478			a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
479			return false
480		}
481		if a.HasDependency && a.DependencyID != depID(j) {
482			return false
483		}
484		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
485		// 由单依赖字段推导后再比较。
486		aDeps := append([]uint64(nil), a.Dependencies...)
487		if len(aDeps) == 0 && a.HasDependency {
488			aDeps = []uint64{a.DependencyID}
489		}
490		if len(aDeps) != len(j.dependencies) {
491			return false
492		}
493		for i := range j.dependencies {
494			if aDeps[i] != j.dependencies[i] {
495				return false
496			}
497		}
498		if len(a.Values) != len(j.values) {
499			return false
500		}
501		for i := range j.values {
502			if a.Values[i] != j.values[i] {
503				return false
504			}
505		}
506		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
507			return false
508		}
509		for i := range j.effectiveValues {
510			if j.effectiveValues[i] != a.EffectiveValues[i] {
511				return false
512			}
513		}
514		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
515			return false
516		}
517		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
518			return false
519		}
520		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
521			return false
522		}
523		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
524			return false
525		}
526		return true
527	}
528	
529	// archiveResultsValid 按既有计算规则对归档保存的实际输入（effectiveValues，
530	// 已含按顺序追加的上游总和，不再追加）复算总和与平方和，归档中的数值结果
531	// 必须与复算结果完全一致。完整性检查只验证日志、摘要与校验值和所写数字
532	// 自洽，无法识别“数字本身写错但全套字段一致”的记录，因此这里以计算规则
533	// 为准。实际输入按规则会造成 int64 溢出时 ok 为 false，任何数值结果
534	// （包括回绕后的值）都不能作为有效成功结果保留。
535	//
536	// 调用前须已通过 archiveIntact（保证 archive 非空且有效输入非空）。
537	func archiveResultsValid(j *storedJob) bool {
538		a := j.archive
539		sum, sumSquares, _, ok := computeResult(j.effectiveValues, j.seed, nil)
540		if !ok {
541			return false
542		}
543		return a.Sum == sum && a.SumOfSquares == sumSquares
544	}
545	
546	// effectiveInputsCorrespond 校验成功记录中实际参与计算的输入与原始提交
547	// 参数、直接依赖数量之间的对应关系：
548	//   - 原始序列必须非空；
549	//   - 原始序列逐项、按原次序完整出现在实际输入的开头——负数、零与重复
550	//     整数一律按位置判断，不比较总和或平方和，也不忽略次序；
551	//   - 实际输入总长度必须恰好等于原始序列长度加直接依赖数量。无依赖时两份
552	//     序列必须完全相同；有单个或多个依赖时，原始部分之后只能保留每个直接
553	//     上游各占一个位置的追加部分，不能借依赖之名替换、截短原始部分，也不
554	//     能多出未记录的输入。
555	//
556	// 该规则防止把另一份输入的自洽结果挂在原始参数下：例如原始参数为 [2,-3]
557	// 而实际输入被换成 [-3,2] 时，总和与平方和不变，摘要、日志与校验值又只
558	// 绑定实际输入，全套字段仍会自洽，只有按位置比对原始参数并核对追加数量
559	// 才能识别。旧的单依赖记录恢复后依赖列表恰含一个作业号，按同一含义判断。
560	//
561	// 调用前须已通过 archiveIntact（保证 archive 非空、实际输入非空且归档内
562	// 副本与顶层一致）。
563	func effectiveInputsCorrespond(j *storedJob) bool {
564		n := len(j.values)
565		if n == 0 {
566			return false
567		}
568		if len(j.effectiveValues) != n+len(j.dependencies) {
569			return false
570		}
571		for i := 0; i < n; i++ {
572			if j.effectiveValues[i] != j.values[i] {
573				return false
574			}
575		}
576		return true
577	}
578

